import{_ as o,o as a,c as s,a1 as d}from"./chunks/framework.DceXOx8u.js";const h=JSON.parse('{"title":"Pasar a producción","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/es/guide/produccion"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/es/guide/produccion"}]]},"headers":[],"relativePath":"es/guide/produccion.md","filePath":"es/guide/produccion.md"}'),t={name:"es/guide/produccion.md"};function r(i,e,c,n,l,u){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="pasar-a-produccion" tabindex="-1">Pasar a producción <a class="header-anchor" href="#pasar-a-produccion" aria-label="Permalink to &quot;Pasar a producción&quot;">​</a></h1><p>Una lista de comprobación para llevar un bot de &quot;funciona en mi máquina&quot; a un despliegue que puedas dejar corriendo. Cada punto enlaza a la página con los detalles. Empieza por <strong>Todo bot</strong>; las secciones siguientes solo aplican cuando las necesitas.</p><h2 id="todo-bot" tabindex="-1">Todo bot <a class="header-anchor" href="#todo-bot" aria-label="Permalink to &quot;Todo bot&quot;">​</a></h2><h3 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h3><ul><li><strong>Node.js 22 o superior</strong>, y tu app es ESM (<code>&quot;type&quot;: &quot;module&quot;</code> en el <code>package.json</code>, o archivos <code>.mjs</code>). Los paquetes no traen build de CommonJS.</li><li><strong>Un gestor de procesos</strong> reinicia el bot cuando termina: PM2, systemd, <code>restart: unless-stopped</code> de Docker o tu orquestador. Ver <a href="./deploy">Despliegue</a>.</li><li><strong>Apagado ordenado</strong>: ante <code>SIGTERM</code>/<code>SIGINT</code>, llama a <code>await bot.stop({ drain: true, timeout: &#39;15s&#39; })</code> para que las respuestas en vuelo se envíen y se registren antes de que el proceso termine (<a href="./deploy#apagado-ordenado">Apagado ordenado</a>).</li><li><strong>Fija las versiones</strong> (commitea el lockfile). Mientras los paquetes estén en beta, lee las <a href="./migracion-estable">páginas de migración</a> antes de cada actualización.</li></ul><h3 id="estado" tabindex="-1">Estado <a class="header-anchor" href="#estado" aria-label="Permalink to &quot;Estado&quot;">​</a></h3><ul><li><strong>Un store persistente.</strong> El <code>MemoryStore</code> por defecto guarda todo en RAM. Usa <code>SQLiteStore</code> para un proceso o <code>RedisStore</code> para varios (<a href="./store#elegir-un-store">Store persistente</a>).</li><li>Pasa la <strong>instancia</strong> del store: <code>store: new SQLiteStore({ file })</code>. Un string como <code>store: &#39;sqlite&#39;</code> se acepta por compatibilidad, pero sigue creando un <code>MemoryStore</code>.</li><li><strong>Los flujos de varios pasos son <code>.persistent()</code></strong>, para que un usuario a mitad de un flujo lo retome tras un reinicio (<a href="./flujos">Flujos</a>).</li><li><strong>En Node.js 24.19 o superior, usa <code>better-sqlite3</code> 13</strong> con <code>SQLiteStore</code> (<a href="./store#sqlitestore">por qué</a>).</li><li><strong>Volúmenes y copias de seguridad</strong>: la carpeta de la sesión de WhatsApp (<code>sessions/</code>) y la de datos (<code>data/</code>) están en disco persistente y se respaldan juntas (<a href="./deploy#copias-de-seguridad">Copias de seguridad</a>).</li></ul><h3 id="secretos" tabindex="-1">Secretos <a class="header-anchor" href="#secretos" aria-label="Permalink to &quot;Secretos&quot;">​</a></h3><ul><li>Los tokens, claves de API y secretos de webhook salen del entorno (o de tu gestor de secretos), nunca del código. El framework no lee ninguna variable de entorno por su cuenta: tú las pasas a las opciones del provider (<a href="./deploy#variables-de-entorno">Variables de entorno</a>).</li><li><code>sessions/</code>, <code>.env</code>, <code>*.db</code> y <code>*.qr.png</code> están en <code>.gitignore</code> y nunca se copian a una imagen de Docker.</li></ul><h3 id="webhooks-cloud-api-webhook-de-telegram-twilio" tabindex="-1">Webhooks (Cloud API, webhook de Telegram, Twilio…) <a class="header-anchor" href="#webhooks-cloud-api-webhook-de-telegram-twilio" aria-label="Permalink to &quot;Webhooks (Cloud API, webhook de Telegram, Twilio…)&quot;">​</a></h3><ul><li>Servidos por <strong>HTTPS</strong> y con la verificación de firma del canal configurada (<code>appSecret</code>, <code>webhookSecret</code>…). Nunca pongas <code>allowUnsignedWebhooks: true</code> en producción (<a href="./seguridad#lista-de-comprobacion-para-produccion">Seguridad</a>).</li><li>La firma se comprueba sobre el <strong>body crudo</strong>: no pongas un parser de JSON delante de la ruta del webhook (<a href="./servidor">Servidor de webhooks</a>).</li></ul><h3 id="observabilidad" tabindex="-1">Observabilidad <a class="header-anchor" href="#observabilidad" aria-label="Permalink to &quot;Observabilidad&quot;">​</a></h3><ul><li><strong>Logs</strong>: pasa tu propio <code>logger</code> de pino (o deja el integrado, que registra desde <code>warn</code>). Los ids de chat y de remitente van hasheados en los logs por defecto (<code>logIds: &#39;hash&#39;</code>); déjalo así fuera de la depuración local.</li><li><strong>Errores</strong>: escucha <code>bot.on(&#39;error&#39;, …)</code> y envíalos a tu sistema de seguimiento de errores.</li><li><strong>Salud y métricas</strong>: expón un endpoint de liveness/readiness y <code>bot.metrics()</code> en formato Prometheus (<a href="./deploy#comprobaciones-de-salud">Comprobaciones de salud</a>, <a href="./operations#metricas-de-runtime">Operación</a>).</li></ul><h3 id="limites-de-los-canales" tabindex="-1">Límites de los canales <a class="header-anchor" href="#limites-de-los-canales" aria-label="Permalink to &quot;Límites de los canales&quot;">​</a></h3><ul><li><strong>WhatsApp con Baileys</strong>: deja activado el rate limiter del provider y evita los envíos masivos no solicitados (<a href="./rate-limiting">Rate limiting</a>).</li><li><strong>Cloud API</strong>: respuestas libres solo dentro de la ventana de 24 horas; fuera de ella, plantillas (<a href="./ventana-24h">Ventana de 24 h de WhatsApp</a>).</li><li><strong>Crecimiento del log de mensajes</strong>: los stores persistentes guardan todos los mensajes salvo que pongas <code>maxMessagesPerChat</code> (<a href="./store#sqlitestore">Store persistente</a>).</li></ul><h2 id="cuando-necesitas-mas" tabindex="-1">Cuando necesitas más <a class="header-anchor" href="#cuando-necesitas-mas" aria-label="Permalink to &quot;Cuando necesitas más&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Necesitas…</th><th>Activa</th><th>Guía</th></tr></thead><tbody><tr><td>Ninguna respuesta perdida ni duplicada si el proceso cae a mitad de un mensaje</td><td><code>BotConfig.durability</code> con un backend persistente</td><td><a href="./durabilidad">Procesamiento durable</a></td></tr><tr><td>Recordatorios e informes que sobreviven a reinicios y corren una sola vez con varias réplicas</td><td>Tareas durables (<code>{ id }</code>) + <code>BotConfig.scheduler</code></td><td><a href="./scheduler#tareas-durables-sobreviven-a-reinicios-una-replica-por-ejecucion">Scheduler</a></td></tr><tr><td>Varios procesos del mismo bot (failover, despliegues sin corte, volumen de webhooks)</td><td><code>BotConfig.coordination</code> + <code>RedisStore</code></td><td><a href="./replicas">Varias réplicas</a></td></tr><tr><td>Redis Cluster en lugar de un Redis único</td><td>El layout de claves <code>&#39;cluster&#39;</code></td><td><a href="./redis-cluster">Redis Cluster</a></td></tr><tr><td>Ver dónde se va el tiempo de cada mensaje</td><td><code>BotConfig.telemetry</code></td><td><a href="./trazas">Trazas</a></td></tr></tbody></table><p>Todo esto es opt-in: sin la opción, el bot funciona exactamente igual que antes.</p><h2 id="que-paquetes-estan-publicados" tabindex="-1">Qué paquetes están publicados <a class="header-anchor" href="#que-paquetes-estan-publicados" aria-label="Permalink to &quot;Qué paquetes están publicados&quot;">​</a></h2><p>Los paquetes de npm (36) son <code>@botmesh/core</code>; los canales <code>@botmesh/baileys</code>, <code>@botmesh/meta</code>, <code>@botmesh/telegram</code>, <code>@botmesh/messenger</code>, <code>@botmesh/instagram</code>, <code>@botmesh/discord</code>, <code>@botmesh/evolution</code>, <code>@botmesh/wppconnect</code>, <code>@botmesh/twilio</code>, <code>@botmesh/gupshup</code>, <code>@botmesh/gohighlevel</code> y <code>@botmesh/email</code>; los stores <code>@botmesh/sqlite-store</code>, <code>@botmesh/redis-store</code>, <code>@botmesh/postgres-store</code>, <code>@botmesh/mysql-store</code> y <code>@botmesh/mongo-store</code>; la infraestructura <code>@botmesh/http</code>, <code>@botmesh/graph-core</code>, <code>@botmesh/wa-gateway-kit</code>, <code>@botmesh/server</code>, <code>@botmesh/events</code> y <code>@botmesh/otel</code>; los plugins <code>@botmesh/ai</code>, <code>@botmesh/rag</code>, <code>@botmesh/voice</code>, <code>@botmesh/nlu</code>, <code>@botmesh/dialogflow</code>, <code>@botmesh/chatwoot</code>, <code>@botmesh/tickets</code> y <code>@botmesh/moderation</code>; y el tooling <code>@botmesh/flow-schema</code>, <code>@botmesh/mcp</code>, <code>eslint-plugin-botmesh</code> y <code>create-botmesh</code>. Los 36 están en npm. Diez se publicaron por primera vez durante la alpha (<code>core</code>, <code>baileys</code>, <code>meta</code>, <code>telegram</code>, <code>sqlite-store</code>, <code>redis-store</code>, <code>ai</code>, <code>http</code>, <code>graph-core</code> y <code>create-botmesh</code>); los otros 26 se publicaron por primera vez con la beta. Algunas páginas describen además paquetes que de momento solo están en el <a href="https://github.com/andresayac/botmesh/tree/main/packages" target="_blank" rel="noreferrer">repositorio</a> (el canal de TikTok, <code>@botmesh/manager</code>, el sandbox…), y cada una lo indica. Planifica un despliegue de producción sobre los publicados.</p><h2 id="antes-de-cada-version-de-tu-bot" tabindex="-1">Antes de cada versión de tu bot <a class="header-anchor" href="#antes-de-cada-version-de-tu-bot" aria-label="Permalink to &quot;Antes de cada versión de tu bot&quot;">​</a></h2><ul><li>Los tests pasan con <code>createTestBot</code> / <code>MockProvider</code> (<a href="./testing">Testing</a>).</li><li>Los archivos o bases de datos del store tienen copia <strong>antes</strong> de actualizar <code>@botmesh/sqlite-store</code>: una versión anterior no puede abrir un esquema más nuevo (<a href="./store#versiones-del-esquema-y-actualizaciones">Versiones del esquema</a>).</li><li>Con réplicas, todas corren una versión que entiende las opciones que activas (por ejemplo <code>coordination.handover.flows: &#39;forward&#39;</code>).</li></ul>',22)])])}const m=o(t,[["render",r]]);export{h as __pageData,m as default};
